import { env } from './env.js';

let glCanvas = null;
let gl = null;
let quadBuffer = null;
const shaderPrograms = {};
let sharedTexture = null;
let noiseTexture = null;
let isWebGL2 = false;

const noiseDataUri = "data:image/png;base64,";

/**
 * Initializes and returns the shared WebGL context and buffers
 */
export function getWebGL() {
  if (!glCanvas) {
    glCanvas = document.createElement('canvas');
    gl = glCanvas.getContext('webgl2', {
      premultipliedAlpha: false,
      preserveDrawingBuffer: true,
    });
    if (gl) {
      isWebGL2 = true;
    } else {
      gl =
        glCanvas.getContext('webgl', {
          premultipliedAlpha: false,
          preserveDrawingBuffer: true,
        }) ||
        glCanvas.getContext('experimental-webgl', {
          premultipliedAlpha: false,
          preserveDrawingBuffer: true,
        });
      isWebGL2 = false;
    }

    if (gl) {
      quadBuffer = gl.createBuffer();
      gl.bindBuffer(gl.ARRAY_BUFFER, quadBuffer);
      gl.bufferData(
        gl.ARRAY_BUFFER,
        new Float32Array([-1, -1, 1, -1, -1, 1, 1, 1]),
        gl.STATIC_DRAW
      );

      sharedTexture = gl.createTexture();
      gl.bindTexture(gl.TEXTURE_2D, sharedTexture);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);

      // Create Noise Texture for Paper and organic shaders
      noiseTexture = gl.createTexture();
      gl.bindTexture(gl.TEXTURE_2D, noiseTexture);
      gl.texImage2D(
        gl.TEXTURE_2D,
        0,
        gl.RGBA,
        1,
        1,
        0,
        gl.RGBA,
        gl.UNSIGNED_BYTE,
        new Uint8Array([128, 128, 128, 255])
      );
      const noiseImg = new Image();
      noiseImg.onload = () => {
        gl.bindTexture(gl.TEXTURE_2D, noiseTexture);
        gl.texImage2D(
          gl.TEXTURE_2D,
          0,
          gl.RGBA,
          gl.RGBA,
          gl.UNSIGNED_BYTE,
          noiseImg
        );
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.REPEAT);
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.REPEAT);
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
        gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
      };
      noiseImg.src = noiseDataUri;
    }
  }
  return { glCanvas, gl, quadBuffer, sharedTexture, noiseTexture, isWebGL2 };
}

/**
 * Compiles a GLSL shader
 */
export function compileShader(glContext, type, source) {
  const shader = glContext.createShader(type);
  glContext.shaderSource(shader, source);
  glContext.compileShader(shader);
  if (!glContext.getShaderParameter(shader, glContext.COMPILE_STATUS)) {
    console.error('Shader compile error:', glContext.getShaderInfoLog(shader));
    glContext.deleteShader(shader);
    return null;
  }
  return shader;
}

/**
 * Gets or compiles and links a WebGL program
 */
export function getOrCreateProgram(id, fsSource, customVsSource = null) {
  const { gl } = getWebGL();
  if (!gl) return null;
  if (shaderPrograms[id]) return shaderPrograms[id];

  let vsSource = customVsSource;
  if (!vsSource) {
    if (fsSource.trim().startsWith('#version 300 es')) {
      vsSource = `#version 300 es
        in vec2 a_position;
        out vec2 v_imageUV;
        out vec2 v_uv;
        void main() {
          vec2 uv = (a_position + 1.0) * 0.5;
          v_uv = uv;
          v_imageUV = vec2(uv.x, 1.0 - uv.y);
          gl_Position = vec4(a_position, 0.0, 1.0);
        }
      `;
    } else {
      vsSource = `
        attribute vec2 a_position;
        varying vec2 v_uv;
        void main() {
          v_uv = (a_position + 1.0) * 0.5;
          v_uv.y = 1.0 - v_uv.y;
          gl_Position = vec4(a_position, 0.0, 1.0);
        }
      `;
    }
  }

  const vs = compileShader(gl, gl.VERTEX_SHADER, vsSource);
  const fs = compileShader(gl, gl.FRAGMENT_SHADER, fsSource);
  if (!vs || !fs) return null;

  const prog = gl.createProgram();
  gl.attachShader(prog, vs);
  gl.attachShader(prog, fs);
  gl.linkProgram(prog);
  if (!gl.getProgramParameter(prog, gl.LINK_STATUS)) {
    console.error('Program link error for ' + id + ':', gl.getProgramInfoLog(prog));
    return null;
  }

  const positionLocation = gl.getAttribLocation(prog, 'a_position');
  shaderPrograms[id] = { prog, positionLocation };
  return shaderPrograms[id];
}

/**
 * Converts a hex color string to normalized RGB float array [0..1]
 */
export function hexToRgb(hex) {
  if (!hex || hex[0] !== '#') return [0, 0, 0];
  let c = hex.substring(1);
  if (c.length === 3) c = c.split('').map((x) => x + x).join('');
  const num = parseInt(c, 16);
  return [
    ((num >> 16) & 255) / 255,
    ((num >> 8) & 255) / 255,
    (num & 255) / 255,
  ];
}

// ---------------- Shape Materials Architecture ----------------

export const SHAPE_OPTIONS = [
  'fullCanvas',
  'sphere',
  'roundedBox',
  'squircle',
  'capsule',
  'ring',
  'hexagon',
  'star',
  'heart',
  'triangle',
  'cross',
  'blob',
];

export function shapeGroup(defaults = {}) {
  return {
    title: 'Shape & Placement',
    controls: [
      {
        key: 'shape',
        label: 'Shape / Canvas',
        type: 'select',
        options: SHAPE_OPTIONS,
        value: defaults.shape || 'fullCanvas',
      },
      {
        key: 'scale',
        label: 'Scale',
        type: 'range',
        min: 0.2,
        max: 2,
        step: 0.02,
        value: 1,
      },
      {
        key: 'rotation',
        label: 'Rotation',
        type: 'range',
        min: -180,
        max: 180,
        step: 1,
        value: 0,
        unit: '°',
      },
      {
        key: 'centerX',
        label: 'Center X',
        type: 'range',
        min: 0,
        max: 1,
        step: 0.01,
        value: 0.5,
      },
      {
        key: 'centerY',
        label: 'Center Y',
        type: 'range',
        min: 0,
        max: 1,
        step: 0.01,
        value: 0.5,
      },
      {
        key: 'edgeSoftness',
        label: 'Edge softness',
        type: 'range',
        min: 0,
        max: 1,
        step: 0.01,
        value: 0.05,
      },
      {
        key: 'backgroundDim',
        label: 'Media dim',
        type: 'range',
        min: 0,
        max: 1,
        step: 0.01,
        value:
          defaults.backgroundDim !== undefined ? defaults.backgroundDim : 0.55,
      },
      {
        key: 'mediaReflect',
        label: defaults.mediaLabel || 'Reflect media',
        type: 'range',
        min: 0,
        max: 1,
        step: 0.01,
        value:
          defaults.mediaReflect !== undefined ? defaults.mediaReflect : 0.3,
      },
    ],
  };
}

export const SHAPE_COMMON_FS = `#version 300 es
  precision highp float;
  in mediump vec2 v_imageUV;
  in mediump vec2 v_uv;
  out vec4 fragColor;

  uniform sampler2D u_image;
  uniform vec2 u_res;
  uniform float u_time;
  uniform int u_shape;
  uniform float u_scale;
  uniform float u_rotation;
  uniform float u_centerX;
  uniform float u_centerY;
  uniform float u_edgeSoftness;
  uniform float u_backgroundDim;
  uniform float u_mediaReflect;

  #define PI 3.14159265359
  #define TAU 6.28318530718

  float g_ca = 1.0;
  float g_sa = 0.0;

  float hash21(vec2 p) {
    vec3 p3 = fract(vec3(p.xyx) * 0.1031);
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.x + p3.y) * p3.z);
  }
  float hash31(vec3 p3) {
    p3 = fract(p3 * 0.1031);
    p3 += dot(p3, p3.zyx + 31.32);
    return fract((p3.x + p3.y) * p3.z);
  }
  float vnoise(vec3 p) {
    vec3 i = floor(p);
    vec3 f = fract(p);
    f = f * f * f * (f * (f * 6.0 - 15.0) + 10.0);
    float a = hash31(i);
    float b = hash31(i + vec3(1.0, 0.0, 0.0));
    float c = hash31(i + vec3(0.0, 1.0, 0.0));
    float d = hash31(i + vec3(1.0, 1.0, 0.0));
    float e = hash31(i + vec3(0.0, 0.0, 1.0));
    float g = hash31(i + vec3(1.0, 0.0, 1.0));
    float h = hash31(i + vec3(0.0, 1.0, 1.0));
    float k = hash31(i + vec3(1.0, 1.0, 1.0));
    return mix(mix(mix(a, b, f.x), mix(c, d, f.x), f.y),
               mix(mix(e, g, f.x), mix(h, k, f.x), f.y), f.z);
  }
  float fbm4(vec3 p) {
    float a = 0.5;
    float s = 0.0;
    for (int i = 0; i < 4; i++) {
      s += a * vnoise(p);
      p = p * 2.03 + vec3(1.7, 9.2, 3.1);
      a *= 0.5;
    }
    return s / 0.9375;
  }
  float lum(vec3 c) { return dot(c, vec3(0.299, 0.587, 0.114)); }

  vec3 imageNormal(vec2 uv, float strength) {
    vec2 texel = 1.0 / u_res;
    float lL = lum(texture(u_image, uv - vec2(texel.x * 2.0, 0.0)).rgb);
    float lR = lum(texture(u_image, uv + vec2(texel.x * 2.0, 0.0)).rgb);
    float lU = lum(texture(u_image, uv - vec2(0.0, texel.y * 2.0)).rgb);
    float lD = lum(texture(u_image, uv + vec2(0.0, texel.y * 2.0)).rgb);
    vec2 grad = vec2(lR - lL, lD - lU);
    return normalize(vec3(-grad * strength, 1.0));
  }

  float dot2(vec2 v) { return dot(v, v); }
  float sdBox(vec2 p, vec2 b) {
    vec2 d = abs(p) - b;
    return length(max(d, 0.0)) + min(max(d.x, d.y), 0.0);
  }
  float sdSeg(vec2 p, vec2 a, vec2 b) {
    vec2 pa = p - a;
    vec2 ba = b - a;
    float h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
    return length(pa - ba * h);
  }
  float sdHex(vec2 p, float r) {
    const vec3 k = vec3(-0.866025404, 0.5, 0.577350269);
    p = abs(p);
    p -= 2.0 * min(dot(k.xy, p), 0.0) * k.xy;
    p -= vec2(clamp(p.x, -k.z * r, k.z * r), r);
    return length(p) * sign(p.y);
  }
  float sdStar5(vec2 p, float r, float rf) {
    const vec2 k1 = vec2(0.809016994375, -0.587785252292);
    const vec2 k2 = vec2(-0.809016994375, -0.587785252292);
    p.x = abs(p.x);
    p -= 2.0 * max(dot(k1, p), 0.0) * k1;
    p -= 2.0 * max(dot(k2, p), 0.0) * k2;
    p.x = abs(p.x);
    p.y -= r;
    vec2 ba = rf * vec2(-k1.y, k1.x) - vec2(0.0, 1.0);
    float h = clamp(dot(p, ba) / dot(ba, ba), 0.0, r);
    return length(p - ba * h) * sign(p.y * ba.x - p.x * ba.y);
  }
  float sdHeart(vec2 p) {
    p.x = abs(p.x);
    if (p.y + p.x > 1.0) return sqrt(dot2(p - vec2(0.25, 0.75))) - 0.35355339;
    return sqrt(min(dot2(p - vec2(0.0, 1.0)), dot2(p - 0.5 * max(p.x + p.y, 0.0)))) * sign(p.x - p.y);
  }
  float sdTri(vec2 p, float r) {
    const float k = 1.7320508;
    p.x = abs(p.x) - r;
    p.y = p.y + r / k;
    if (p.x + k * p.y > 0.0) p = vec2(p.x - k * p.y, -k * p.x - p.y) / 2.0;
    p.x -= clamp(p.x, -2.0 * r, 0.0);
    return -length(p) * sign(p.y);
  }
  float sdShape(vec2 p) {
    if (u_shape == 0) return -1.0;
    if (u_shape == 1) return length(p) - 1.0;
    if (u_shape == 2) return sdBox(p, vec2(0.88, 0.62) - 0.32) - 0.32;
    if (u_shape == 3) return (pow(pow(abs(p.x), 4.0) + pow(abs(p.y), 4.0), 0.25) - 1.0) * 0.95;
    if (u_shape == 4) return sdSeg(p, vec2(-0.55, 0.0), vec2(0.55, 0.0)) - 0.5;
    if (u_shape == 5) return abs(length(p) - 0.72) - 0.28;
    if (u_shape == 6) return sdHex(p, 0.88);
    if (u_shape == 7) return sdStar5(p, 1.0, 0.45);
    if (u_shape == 8) return sdHeart(p * 0.6 + vec2(0.0, 0.5)) / 0.6;
    if (u_shape == 9) return sdTri(p, 0.8);
    if (u_shape == 10) return min(sdBox(p, vec2(0.78, 0.2)), sdBox(p, vec2(0.2, 0.78))) - 0.12;
    float th = atan(p.y, p.x);
    float rb = 0.82 + 0.10 * sin(3.0 * th + u_time * 0.3) + 0.06 * sin(5.0 * th - u_time * 0.2) + 0.03 * sin(7.0 * th + u_time * 0.45);
    return (length(p) - rb) * 0.8;
  }

  vec2 toScreen(vec2 v) {
    return vec2(g_ca * v.x + g_sa * v.y, -g_sa * v.x + g_ca * v.y);
  }
  vec2 toShape(vec2 v) {
    return vec2(g_ca * v.x - g_sa * v.y, g_sa * v.x + g_ca * v.y);
  }

  void shapeSetup(out vec2 p, out float d, out vec2 gd, out float alpha) {
    float asp = u_res.x / u_res.y;
    if (u_shape == 0) {
      p = (v_uv - 0.5) * 2.0 * vec2(asp, 1.0);
      d = -1.0;
      gd = vec2(0.0);
      alpha = 1.0;
      g_ca = 1.0;
      g_sa = 0.0;
      return;
    }
    vec2 q = (v_uv - 0.5) * 2.0 * vec2(asp, 1.0);
    q -= vec2((u_centerX - 0.5) * 2.0 * asp, (0.5 - u_centerY) * 2.0);
    float a = radians(-u_rotation);
    g_ca = cos(a);
    g_sa = sin(a);
    q = toShape(q);
    float sc = max(u_scale, 0.05) * 0.62;
    p = q / sc;
    d = sdShape(p);
    float e = 0.004;
    vec2 g = vec2(sdShape(p + vec2(e, 0.0)) - sdShape(p - vec2(e, 0.0)),
                  sdShape(p + vec2(0.0, e)) - sdShape(p - vec2(0.0, e)));
    g = g / max(length(g), 1e-5);
    gd = toScreen(g);
    float px = 2.0 / u_res.y / sc;
    float soft = u_edgeSoftness * 0.25;
    alpha = 1.0 - smoothstep(-px * 0.75, px * 0.75 + soft, d);
  }

  vec3 bevelNormal(vec2 gd, float d, float w, float shapeAmt) {
    float t = clamp(-d / max(w, 1e-3), 0.0, 1.0);
    float h = sqrt(max(2.0 * t - t * t, 1e-4));
    float sFillet = (1.0 - t) / h;
    float sMach = 6.0 * (1.0 - smoothstep(0.0, 0.22, t))
                + 0.95 * smoothstep(0.0, 0.12, t) * (1.0 - smoothstep(0.62, 0.78, t))
                + 0.55 * exp(-pow((t - 0.8) / 0.07, 2.0));
    sMach *= 1.0 - smoothstep(0.85, 1.0, t);
    float s = mix(sFillet, sMach, shapeAmt);
    return normalize(vec3(gd * s, 1.0));
  }

  vec3 sceneBg(float d) {
    vec3 m = texture(u_image, v_imageUV).rgb;
    vec3 bg = m * (1.0 - u_backgroundDim);
    float occl = exp(-max(d, 0.0) * 3.5) * 0.35;
    return bg * (1.0 - occl);
  }

  vec3 mediaEnv(vec3 r, float blur) {
    vec2 off = vec2(r.x, -r.y) * 0.45;
    vec3 acc = texture(u_image, clamp(v_imageUV + off, 0.001, 0.999)).rgb;
    for (int i = 0; i < 8; i++) {
      float a = float(i) * 0.785398;
      vec2 o = vec2(cos(a), sin(a)) * blur * 0.06;
      acc += texture(u_image, clamp(v_imageUV + off + o, 0.001, 0.999)).rgb;
    }
    return acc / 9.0;
  }

  float sbox(vec2 a, vec2 c, vec2 hs, float soft) {
    vec2 q = abs(a - c) - hs;
    return 1.0 - smoothstep(-soft, soft, max(q.x, q.y));
  }

  vec3 studio(vec3 r, float rot, float soft, float depth, vec3 warm, vec3 cool, float spectral) {
    float cr = cos(rot);
    float sr = sin(rot);
    r = vec3(cr * r.x + sr * r.z, r.y, -sr * r.x + cr * r.z);
    float az = atan(r.x, r.z);
    float el = asin(clamp(r.y, -1.0, 1.0));
    vec2 ae = vec2(az, el);
    float s = soft * 0.35 + 0.012;
    float skyT = smoothstep(-0.2, 1.0, el);
    float base = mix(mix(0.30, 0.05, depth), mix(0.55, 0.20, depth), skyT);
    vec3 col = vec3(base);
    float floorT = 1.0 - smoothstep(-0.7, 0.02, el);
    vec3 floorCol = mix(vec3(0.18), vec3(0.015), depth) * mix(vec3(1.0), cool * 1.1, spectral * 0.7);
    col = mix(col, floorCol, floorT);
    float flagL = sbox(ae, vec2(-1.15, 0.2), vec2(0.28, 1.2), s);
    float flagR = sbox(ae, vec2(1.15, 0.2), vec2(0.28, 1.2), s);
    col *= 1.0 - depth * 0.9 * max(flagL, flagR);
    float box = sbox(ae, vec2(0.0, 0.30), vec2(0.62, 0.55), s * 1.2);
    col = mix(col, vec3(3.4), box);
    col += box * 0.9 * smoothstep(0.0, 0.85, el);
    float warmBand = sbox(ae, vec2(0.0, 0.02), vec2(2.6, 0.045), s);
    col += warm * warmBand * 2.4 * spectral;
    float stripL = sbox(ae, vec2(-0.82, 0.25), vec2(0.035, 0.8), s);
    float stripR = sbox(ae, vec2(0.86, 0.25), vec2(0.03, 0.8), s);
    col += mix(vec3(1.0), warm, spectral) * stripL * 2.2;
    col += mix(vec3(1.0), cool, spectral) * stripR * 2.6;
    col += vec3(1.0) * sbox(ae, vec2(0.0, 1.15), vec2(1.2, 0.12), s) * 1.8;
    float behind = smoothstep(1.7, 2.3, abs(az));
    col = mix(col, vec3(mix(0.08, 0.01, depth)), behind * 0.8);
    col += mix(vec3(1.0), cool, spectral) * sbox(vec2(abs(az), el), vec2(2.9, 0.2), vec2(0.08, 0.9), s) * 2.0;
    return col;
  }

  vec3 tone(vec3 c) {
    c = c / (1.0 + c * 0.28);
    return clamp(c, 0.0, 1.0);
  }
`;

export function makeShapeEffect({
  id,
  label,
  fragment,
  groups,
  defaults = {},
  describe,
}) {
  const allGroups = [shapeGroup(defaults), ...groups];
  const locs = {};
  return {
    id,
    label,
    groups: allGroups,
    draw(v, dt) {
      const { W, H, ctx } = env;
      env.time += dt;

      const { glCanvas, gl, quadBuffer, sharedTexture } = getWebGL();
      if (!gl) {
        ctx.drawImage(env.sourceCanvas, 0, 0, W, H);
        return `${label} (WebGL fallback)`;
      }

      const progInfo = getOrCreateProgram(
        'shapeMat_' + id,
        SHAPE_COMMON_FS + fragment
      );
      if (!progInfo) return `${label} shader error`;

      glCanvas.width = W;
      glCanvas.height = H;
      gl.viewport(0, 0, W, H);
      gl.useProgram(progInfo.prog);

      gl.bindBuffer(gl.ARRAY_BUFFER, quadBuffer);
      gl.enableVertexAttribArray(progInfo.positionLocation);
      gl.vertexAttribPointer(
        progInfo.positionLocation,
        2,
        gl.FLOAT,
        false,
        0,
        0
      );

      gl.activeTexture(gl.TEXTURE0);
      gl.bindTexture(gl.TEXTURE_2D, sharedTexture);
      gl.texImage2D(
        gl.TEXTURE_2D,
        0,
        gl.RGBA,
        gl.RGBA,
        gl.UNSIGNED_BYTE,
        env.sourceCanvas
      );

      const loc = (name) => {
        if (!(name in locs))
          locs[name] = gl.getUniformLocation(progInfo.prog, name);
        return locs[name];
      };
      gl.uniform1i(loc('u_image'), 0);
      gl.uniform2f(loc('u_res'), W, H);
      gl.uniform1f(loc('u_time'), env.time);

      allGroups.forEach((g) =>
        g.controls.forEach((c) => {
          const l = loc('u_' + c.key);
          if (!l) return;
          const val = v[c.key];
          if (c.type === 'color') {
            const rgb = hexToRgb(val);
            gl.uniform3f(l, rgb[0], rgb[1], rgb[2]);
          } else if (c.type === 'select') {
            gl.uniform1i(l, Math.max(0, c.options.indexOf(val)));
          } else if (c.type === 'checkbox') {
            gl.uniform1f(l, val ? 1 : 0);
          } else if (c.type === 'range') {
            gl.uniform1f(l, Number(val));
          }
        })
      );

      gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);
      ctx.drawImage(glCanvas, 0, 0);
      return describe ? describe(v) : `${label} · ${v.shape}`;
    },
  };
}
